function leerCanal() {
  try {
    const out = execFileSync(
      PYTHON,
      ["arnes\\canal.py", "leer"],
      { cwd: INGENIERO, encoding: "utf-8", timeout: 15000,
        env: { ...process.env, INGENIERO_QUIEN: QUIEN } },
    );
    const texto = (out || "").trim();
    if (!texto) return "";
    try {
      const j = JSON.parse(texto);
      const ctx = j.hookSpecificOutput && j.hookSpecificOutput.additionalContext;
      return typeof ctx === "string" ? ctx : "";
    } catch {
      return "";
    }
  } catch {
    return "";
  }
}

propuesta.texto_nuevo:
function leerCanal() {
  try {
    const out = execFileSync(
      PYTHON,
      ["arnes\\canal.py", "leer", "--sin-marcar"],
      { cwd: INGENIERO, encoding: "utf-8", timeout: 15000,
        env: { ...process.env, INGENIERO_QUIEN: QUIEN } },
    );
    const texto = (out || "").trim();
    if (!texto) return null;
    try {
      const j = JSON.parse(texto);
      const ctx = j.additionalContext;
      const rutas = j.rutas;
      if (typeof ctx === "string" && ctx) return { ctx, rutas };
      return null;
    } catch {
      return null;
    }
  } catch {
    return null;
  }
}

function marcarCanal(rutas) {
  try {
    if (!rutas || !rutas.length) return;
    execFileSync(
      PYTHON,
      ["arnes\\canal.py", "marcar", ...rutas],
      { cwd: INGENIERO, encoding: "utf-8", timeout: 15000,
        env: { ...process.env, INGENIERO_QUIEN: QUIEN } },
    );
  } catch (e) {
    log("marcarCanal fallo: " + e);
  }
}

